"""Write one era's stored model records with that era's own code (the external audit of 2026-10-16, A14).

Run from an export of the era's tree, with it first on the path, e.g.

    git archive 6c9c73b adroit | tar -x -C /tmp/era1
    python -c "import sys; sys.path.insert(0, '/tmp/era1'); exec(open('tests/fixtures/schema_eras/generate.py').read())" \
        tests/fixtures/schema_eras/era1

It writes a catalog with one intake session (a typed step and its approval into the library) and an approved
model's YAML, and an ``index.json`` naming them. The fixtures are frozen: they are what that code wrote, and are
never regenerated by the current code.
"""

import json
import sys
from pathlib import Path

import yaml

import adroit
from adroit.library.personal import Catalog
from adroit.orchestrator import ideas
from adroit.orchestrator.model_approval import model_identity, select_model, write_approved
from adroit.orchestrator.model_intake import Intake
from adroit.parameter_space.simplified import model

# Only when run as above (exec, or a script): importing this file writes nothing (2026-10-24: imported during a test
# run, it wrote an era's library into a folder named after pytest's first argument, "-q").
if __name__ == "__main__":
    out = Path(sys.argv[1])
    if out.exists():
        raise SystemExit(f"{out} exists: fixtures are frozen")
    spec = model("vector", 10, 125, .001, .25)
    catalog = Catalog(out / "library")
    intake = Intake(catalog)
    session = intake.start()
    step = intake.step(session.session_id, "typed", yaml.safe_dump(spec.model_dump(mode="json")))
    choice = step.choices[0]
    revision = intake.approve(session.session_id, step.step_id, 0, confirmed=True,
                              expected_model_hash=model_identity(choice.spec), tex=choice.tex)
    selected, approval = select_model(ideas.from_lagrangian(spec))
    write_approved(out / "approved.yaml", selected, approval)
    (out / "index.json").write_text(json.dumps({
        "code": str(Path(adroit.__file__).parent), "revision": revision.reference, "session": session.session_id,
        "step": step.step_id, "model_sha256": revision.model_sha256}, indent=1))
    print(out, revision.reference)
